#!/usr/bin/env python3
"""Underline all headlines in quarterly_report.docx.

Headlines are identified via paragraph styles: style names/ids containing
'heading' or 'title', plus the default-template numeric style ids (1..9).
Every text run inside a headline paragraph gets <w:u w:val="single"/>.
"""
import os
import re
import sys
import zipfile
import xml.etree.ElementTree as ET

SRC = "quarterly_report.docx"
TMP = "quarterly_report_new.docx"

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
R = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
NS = {
    "w": W,
    "r": R,
    "wp": "http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing",
    "a": "http://schemas.openxmlformats.org/drawingml/2006/main",
    "pic": "http://schemas.openxmlformats.org/drawingml/2006/picture",
    "mc": "http://schemas.openxmlformats.org/markup-compatibility/2006",
    "o": "urn:schemas-microsoft-com:office:office",
    "v": "urn:schemas-microsoft-com:vml",
}
for prefix, uri in NS.items():
    ET.register_namespace(prefix, uri)


def q(tag):
    return "{%s}%s" % (W, tag)


def build_style_map(z):
    """Map styleId -> style name from word/styles.xml."""
    try:
        root = ET.fromstring(z.read("word/styles.xml"))
    except KeyError:
        return {}
    mapping = {}
    for st in root.findall(q("style")):
        sid = st.get(q("styleId"))
        if not sid:
            continue
        name_el = st.find(q("name"))
        name = name_el.get(q("val")) if name_el is not None else ""
        mapping[sid] = name
    return mapping


def is_heading(style_id, style_map):
    if not style_id:
        return False
    name = style_map.get(style_id, "").lower()
    sid = style_id.lower()
    if "heading" in name or "title" in name:
        return True
    if "heading" in sid or "title" in sid:
        return True
    # Default Word template numbers heading styles 1..9
    if re.fullmatch(r"[1-9]", style_id):
        return True
    return False


def para_text(p):
    parts = []
    for t in p.iter(q("t")):
        parts.append(t.text or "")
    return "".join(parts)


def underline_paragraph(p):
    """Add underline to every run's rPr in the paragraph."""
    for r in p.findall(q("r")):
        rpr = r.find(q("rPr"))
        if rpr is None:
            rpr = ET.Element(q("rPr"))
            r.insert(0, rpr)
        u = rpr.find(q("u"))
        if u is None:
            u = ET.SubElement(rpr, q("u"))
        u.set(q("val"), "single")


def process_part(z, name, style_map, changed, heading_texts):
    try:
        data = z.read(name)
    except KeyError:
        return
    root = ET.fromstring(data)
    count = 0
    for p in root.iter(q("p")):
        ppr = p.find(q("pPr"))
        style_id = None
        if ppr is not None:
            pstyle = ppr.find(q("pStyle"))
            if pstyle is not None:
                style_id = pstyle.get(q("val"))
        if is_heading(style_id, style_map):
            underline_paragraph(p)
            count += 1
            heading_texts.append((name, style_id, para_text(p)))
    if count:
        changed[name] = ET.tostring(
            root, encoding="UTF-8", xml_declaration=True
        )


def main():
    if not os.path.exists(SRC):
        print("ERROR: %s not found" % SRC)
        return 1

    with zipfile.ZipFile(SRC, "r") as zin:
        style_map = build_style_map(zin)
        changed = {}
        heading_texts = []
        # Process the main document plus any headers/footers.
        names = [n for n in zin.namelist() if not n.endswith("/")]
        for name in names:
            if name.startswith("word/") and (
                name.endswith(".xml") and not name.startswith("word/theme")
                and name != "word/styles.xml"
            ):
                process_part(zin, name, style_map, changed, heading_texts)

        with zipfile.ZipFile(TMP, "w", zipfile.ZIP_DEFLATED) as zout:
            for item in zin.infolist():
                data = zin.read(item.filename)
                if item.filename in changed:
                    data = changed[item.filename]
                zout.writestr(item, data)

    os.replace(TMP, SRC)

    print("Style map (heading-related):")
    for sid, name in sorted(style_map.items()):
        if "heading" in name.lower() or "title" in name.lower():
            print("  %s -> %s" % (sid, name))

    print("\nHeadlines underlined: %d" % len(heading_texts))
    for name, sid, text in heading_texts:
        print("  [%s] (%s) %s" % (name, sid, text[:80]))
    print("DONE")
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Inspect quarterly_report.docx structure: styles and paragraphs."""
import zipfile
import xml.etree.ElementTree as ET

SRC = "quarterly_report.docx"
W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"


def q(tag):
    return "{%s}%s" % (W, tag)


with zipfile.ZipFile(SRC, "r") as z:
    print("== Archive entries ==")
    for n in z.namelist():
        print("  ", n)

    try:
        root = ET.fromstring(z.read("word/styles.xml"))
        print("\n== Styles (styleId -> name) ==")
        for st in root.findall(q("style")):
            sid = st.get(q("styleId"))
            name_el = st.find(q("name"))
            name = name_el.get(q("val")) if name_el is not None else ""
            print("  %s -> %s" % (sid, name))
    except KeyError:
        print("\nNo styles.xml")

    try:
        doc = ET.fromstring(z.read("word/document.xml"))
        print("\n== Paragraphs (index: pStyle | text) ==")
        for i, p in enumerate(doc.iter(q("p"))):
            ppr = p.find(q("pPr"))
            style_id = None
            if ppr is not None:
                ps = ppr.find(q("pStyle"))
                if ps is not None:
                    style_id = ps.get(q("val"))
            parts = []
            for t in p.iter(q("t")):
                parts.append(t.text or "")
            text = "".join(parts)
            # run properties of first run, to see formatting
            rpr_info = ""
            first_r = p.find(q("r"))
            if first_r is not None:
                rpr = first_r.find(q("rPr"))
                if rpr is not None:
                    attrs = []
                    for child in rpr:
                        tag = child.tag.split("}")[-1]
                        val = child.get(q("val")) or child.get(q("color")) or ""
                        attrs.append(tag + (":" + val if val else ""))
                    rpr_info = " [" + ",".join(attrs) + "]"
            print("  %3d | %-12s | %s%s" % (i, style_id, text[:90], rpr_info))
    except KeyError:
        print("\nNo document.xml")

#!/usr/bin/env python3
"""Underline all headlines in quarterly_report.docx.

Also writes a structural analysis to inspect_output.txt so the
headline-detection heuristics can be verified and refined.
"""
import os
import re
import zipfile
import xml.etree.ElementTree as ET

SRC = "quarterly_report.docx"
TMP = "quarterly_report_new.docx"
ANALYSIS = "inspect_output.txt"

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
NS = {
    "w": W,
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
    "wp": "http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing",
    "a": "http://schemas.openxmlformats.org/drawingml/2006/main",
    "pic": "http://schemas.openxmlformats.org/drawingml/2006/picture",
    "mc": "http://schemas.openxmlformats.org/markup-compatibility/2006",
    "o": "urn:schemas-microsoft-com:office:office",
    "v": "urn:schemas-microsoft-com:vml",
}
for prefix, uri in NS.items():
    ET.register_namespace(prefix, uri)


def q(tag):
    return "{%s}%s" % (W, tag)


def build_style_map(z):
    try:
        root = ET.fromstring(z.read("word/styles.xml"))
    except KeyError:
        return {}
    mapping = {}
    for st in root.findall(q("style")):
        sid = st.get(q("styleId"))
        if not sid:
            continue
        name_el = st.find(q("name"))
        name = name_el.get(q("val")) if name_el is not None else ""
        mapping[sid] = name
    return mapping


def para_text(p):
    return "".join(t.text or "" for t in p.iter(q("t")))


def run_format_summary(p):
    """Summarize formatting of the paragraph's runs."""
    infos = []
    for r in p.findall(q("r")):
        rpr = r.find(q("rPr"))
        attrs = []
        if rpr is not None:
            for child in rpr:
                tag = child.tag.split("}")[-1]
                val = child.get(q("val")) or ""
                color = child.get(q("color")) or ""
                sz = child.get(q("sz")) or child.get(q("val")) or ""
                if tag == "b":
                    attrs.append("b")
                elif tag == "u":
                    attrs.append("u:" + (val or "single"))
                elif tag == "sz":
                    attrs.append("sz:" + sz)
                elif tag == "color":
                    attrs.append("color:" + color)
        txt = "".join(t.text or "" for t in r.iter(q("t")))
        infos.append("(%s)%s" % (",".join(attrs), txt[:30]))
    return " ".join(infos) if infos else ""


def is_heading(style_id, style_map):
    if not style_id:
        return False
    name = style_map.get(style_id, "").lower()
    sid = style_id.lower()
    if "heading" in name or "title" in name:
        return True
    if "heading" in sid or "title" in sid:
        return True
    if re.fullmatch(r"[1-9]", style_id):
        return True
    return False


def underline_paragraph(p):
    for r in p.findall(q("r")):
        rpr = r.find(q("rPr"))
        if rpr is None:
            rpr = ET.Element(q("rPr"))
            r.insert(0, rpr)
        u = rpr.find(q("u"))
        if u is None:
            u = ET.SubElement(rpr, q("u"))
        u.set(q("val"), "single")


def process_part(z, name, style_map, changed, headings):
    try:
        data = z.read(name)
    except KeyError:
        return
    root = ET.fromstring(data)
    count = 0
    for p in root.iter(q("p")):
        ppr = p.find(q("pPr"))
        style_id = None
        if ppr is not None:
            ps = ppr.find(q("pStyle"))
            if ps is not None:
                style_id = ps.get(q("val"))
        if is_heading(style_id, style_map):
            underline_paragraph(p)
            count += 1
            headings.append((name, style_id, para_text(p)))
    if count:
        changed[name] = ET.tostring(root, encoding="UTF-8", xml_declaration=True)


def main():
    if not os.path.exists(SRC):
        print("ERROR: %s not found" % SRC)
        return 1

    lines = []
    with zipfile.ZipFile(SRC, "r") as zin:
        lines.append("== Archive entries ==")
        for n in zin.namelist():
            lines.append("  " + n)

        style_map = build_style_map(zin)
        lines.append("\n== Styles ==")
        for sid, name in sorted(style_map.items()):
            lines.append("  %s -> %s" % (sid, name))

        # Dump paragraphs from document + headers/footers
        for name in sorted(zin.namelist()):
            if not (name.startswith("word/") and name.endswith(".xml")):
                continue
            if name.startswith("word/theme") or name in ("word/styles.xml",):
                continue
            try:
                root = ET.fromstring(zin.read(name))
            except KeyError:
                continue
            lines.append("\n== Paragraphs in %s ==" % name)
            for i, p in enumerate(root.iter(q("p"))):
                ppr = p.find(q("pPr"))
                style_id = None
                if ppr is not None:
                    ps = ppr.find(q("pStyle"))
                    if ps is not None:
                        style_id = ps.get(q("val"))
                lines.append(
                    "  %3d | %-12s | %s || %s"
                    % (i, style_id, para_text(p)[:80], run_format_summary(p)[:120])
                )

        changed = {}
        headings = []
        for name in sorted(zin.namelist()):
            if name.startswith("word/") and name.endswith(".xml") and not name.startswith(
                "word/theme"
            ) and name != "word/styles.xml":
                process_part(zin, name, style_map, changed, headings)

        with zipfile.ZipFile(TMP, "w", zipfile.ZIP_DEFLATED) as zout:
            for item in zin.infolist():
                data = zin.read(item.filename)
                if item.filename in changed:
                    data = changed[item.filename]
                zout.writestr(item, data)

    os.replace(TMP, SRC)

    with open(ANALYSIS, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))

    print("Headlines underlined: %d" % len(headings))
    for name, sid, text in headings:
        print("  [%s] (%s) %s" % (name, sid, text[:80]))
    print("Analysis written to %s" % ANALYSIS)
    print("DONE")
    return 0


if __name__ == "__main__":
    main()
